fixedSlug=shopSlugFromPath(location.pathname);const customRouting=configuration.customDomainRouting===true;if(customRouting){try{fixedSlug=await api.resolveDomain(location.hostname.toLowerCase())}catch{fixedSlug=null}if(!fixedSlug){message('الدومين غير موثق أو المحل غير متاح.');throw Error('Unverified domain route')}}
if(fixedSlug){el('shopSelector').hidden=true;el('catalog').elements.slug.value=fixedSlug;}el('app').hidden=false;controls();el('customerAuth').hidden=!api.customerAuthEnabled();const query=new URLSearchParams(location.search),initialShop=fixedSlug||query.get('shop'),initialCurrency=query.get('currency');if(initialShop&&/^[a-z][a-z0-9-]{2,39}$/.test(initialShop)){slug=initialShop;currency=['USD','EUR','SYP'].includes(initialCurrency)?initialCurrency:'USD';el('catalog').elements.slug.value=slug;el('catalog').elements.currency.value=currency;run(()=>catalog())}

const repairLabels={received:'تم الاستلام',diagnosing:'قيد الفحص',repairing:'قيد الإصلاح',ready:'جاهز للاستلام',delivered:'تم التسليم',cancelled:'ملغى'};
async function showRepairStatus(code){
 const result=el('repairTrackingResult'),shop=slug,r=await api.repairStatus(shop,code);if(shop!==slug)return;
 result.replaceChildren();if(!r){result.append(node('p',tr('لا يوجد طلب مطابق لهذا الرمز')));return}
 result.append(node('h3',tr(r.device)),node('p',tr(repairLabels[r.state])),node('p',new Date(r.created_at).toLocaleString(currentLanguage()==='en'?'en-GB':'ar-SY',{timeZone:'Asia/Damascus'})));
 if(r.linked_account===false)result.append(node('p',tr('التفاصيل والتقدير والصور متاحة للحساب المؤكد المرتبط بالطلب فقط.')));
 const e=r.estimate;
 if(e){
  result.append(node('strong',fmt(e.amount_minor,e.currency)),node('p',e.description),node('p',tr(({offered:'بانتظار الموافقة',approved:'مقبول',rejected:'مرفوض',superseded:'ملغى'})[e.state])));
  if(e.state==='offered'&&!r.can_decide)result.append(node('p',tr('الموافقة تحتاج حساب العميل المرتبط.')));
  if(e.state==='offered'&&r.can_decide&&api.signedIn())for(const [label,accept] of [['أوافق على التكلفة',true],['أرفض التكلفة',false]])result.append(button(label,async()=>{if(shop!==slug||!confirm(tr(label)+' — '+fmt(e.amount_minor,e.currency)+'؟'))return;await api.repairDecide(shop,code,e.id,accept);await showRepairStatus(code)}));
 }
 if(r.linked_account&&api.signedIn()&&r.shared_evidence?.length){
  result.append(node('h3',tr('صور الجهاز المشتركة')));
  for(const photo of r.shared_evidence){const box=node('div',''),label=tr(photo.kind==='before'?'قبل الإصلاح':'بعد الإصلاح'),img=document.createElement('img');img.src='data:image/jpeg;base64,'+photo.photo;img.alt=label;img.loading='lazy';img.style.maxWidth='100%';img.style.maxHeight='320px';box.append(node('p',label),img,node('small',new Date(photo.created_at).toLocaleString(currentLanguage()==='en'?'en-GB':'ar-SY',{timeZone:'Asia/Damascus'})));result.append(box)}
 }
}
el('repairPairing').onclick=()=>run(async()=>{if(!api.signedIn()||!slug)return;const s=slug,r=await api.repairPairingCode(s);if(s===slug&&api.signedIn())el('repairPairingCode').textContent=r+' — '+tr('صالح عشر دقائق؛ سلّمه لصاحب المحل فقط.')});
el('repairTrackingForm').onsubmit=e=>{e.preventDefault();run(()=>showRepairStatus(el('repairTrackingCode').value.trim()))};

el('guestSend').onclick=()=>run(async()=>{if(api.signedIn()||!slug||attempt&&!attempt.guest)return;if(!attempt){if(!guestEnabled||!cart.size)return;const name=el('guestName').value.trim(),phone=el('guestPhone').value.trim();if(!name||phone.length<5)throw Error('Contact required');if(!confirm('طلب للاستلام من المحل، دون حجز مخزون أو دفع مسبق؟'))return;attempt=Object.freeze({guest:true,slug,currency,name,phone,requestId:crypto.randomUUID(),lines:Object.freeze([...cart.values()].map(x=>Object.freeze({...x})))});el('pending').textContent='احفظ رمز المتابعة السري حتى لو انقطع الاتصال: '+attempt.requestId;renderCart()}const code=await api.guestSubmit(attempt);attempt=null;cart.clear();el('guestName').value='';el('guestPhone').value='';el('guestTrackCode').value=code;el('pending').textContent='تم إرسال الطلب. احفظ رمز المتابعة: '+code;renderCart();await showGuestTrack(code)});
async function showGuestTrack(code){const r=await api.guestTrack(slug,code),root=el('guestTrackResult');root.replaceChildren();if(!r){root.append(node('p','لا يوجد طلب مطابق'));return}root.append(node('p',({pending:'بانتظار المحل',cancelled:'ملغى',fulfilled:'تم التسليم'})[r.state]),node('strong',fmt(r.total_minor,r.currency)))}
el('guestTrackForm').onsubmit=e=>{e.preventDefault();run(()=>showGuestTrack(el('guestTrackCode').value.trim()))};

let assistantAnswer=null,buildAnswer=null;
function clearAssistant(){el('generatedBuildResult').textContent='';assistantAnswer=null;buildAnswer=null;el('localAssistantQuestion').value='';el('localAssistantResult').replaceChildren();el('suggestBuildResult').replaceChildren()}
async function collectBuildCandidates(){const candidates=[],seen=new Set();let after=null,truncated=false;for(let i=0;i<5;i++){const page=await api.searchCatalog(slug,currency,'',after,50);if(!page)break;for(const item of page.products){if(seen.has(item.id))throw Error('Catalog changed');seen.add(item.id);candidates.push(item)}if(page.products.length<50)break;after=page.products.at(-1).id;if(i===4)truncated=true}return {candidates,truncated}}
function partLabel(k){const part=assistantPartLabel(k);return part?tr(part):k.startsWith('duplicate:')?tr('تكرار')+' '+tr(assistantPartLabel(k.slice(10))||k.slice(10)):k.startsWith('type:')?tr('نوع غير معروف')+': '+k.slice(5):k}
function paintSuggestion(root,answer){root.replaceChildren();if(!answer)return;const {r,count,truncated,shop,cc}=answer;if(shop!==slug||cc!==currency)return;root.append(node('p',tr('اقتراح بالقواعد من منتجات الكتالوج المفحوصة')+': '+count+(truncated?' — '+tr('قد توجد منتجات إضافية لم تُفحص'):'')+'. '+tr('لا يضمن توافق كل المكونات.')));if(!r.items.length){root.append(node('p',r.missing.length?tr('تنقص أنواع القطع')+': '+r.missing.map(partLabel).join('، '):tr('لم نجد تجميعة ضمن الميزانية تحقق الفحوص المدعومة.')));return}root.append(node('strong',tr('الإجمالي المقترح')+': '+fmt(r.total,cc)));for(const x of r.items)root.append(node('p',x.name+' — '+fmt(x.price_minor,cc)));if(r.compatibility.unknown.length)root.append(node('p',tr('توافق غير مؤكد')+': '+r.compatibility.unknown.map(partLabel).join('، ')));root.append(button('استخدام الاقتراح في التجميعة',async()=>{if(attempt||shop!==slug||cc!==currency)return;if(build.size&&!confirm(tr('استبدال التجميعة الحالية؟')))return;build.clear();for(const x of r.items)build.set(x.id,x);renderBuild();renderCatalog();el('buildPanel').scrollIntoView({block:'start'})}))}
async function getSuggestion(budget,gpu){const shop=slug,cc=currency,{candidates,truncated}=await collectBuildCandidates();if(shop!==slug||cc!==currency)throw Error('Store changed');return {shop,cc,count:candidates.length,truncated,r:suggestBuild(candidates,budget,{gpu})}}
function paintAssistant(){const root=el('localAssistantResult');root.replaceChildren();if(!assistantAnswer)return;const {kind}=assistantAnswer;if(kind==='build'){paintSuggestion(root,assistantAnswer.suggestion);return}if(kind==='compatibility'){if(!build.size){root.append(node('p',tr('أضف قطعاً إلى التجميعة الحالية أولاً.')));return}const r=buildCompatibility([...build.values()]);for(const [label,values] of [['تعارضات',r.warnings],['مواصفات ناقصة',r.unknown],['قطع ناقصة',r.missing]])if(values.length)root.append(node('p',tr(label)+': '+values.map(partLabel).join('، ')));root.append(node('p',tr('الفحص محدود بالمواصفات المسجلة؛ راجع الشركة المصنعة.')));return}const answers={currency:'اختر العملة المطابقة للسؤال في الكتالوج، ثم أعد السؤال.',budget:'اكتب ميزانية واحدة رقمية بالعملة المختارة، دون فواصل أو اختصارات.',delivery:'راجع طريقة التسليم المتاحة في السلة. لا يوجد دفع إلكتروني مفعّل.',tracking:'استخدم رمز متابعة الطلب أو الصيانة في قسم المتابعة الموجود.',help:'يمكنني اقتراح تجميعة حسب ميزانية، أو فحص توافق التجميعة الحالية، أو إرشادك إلى التسليم والمتابعة.'};root.append(node('p',tr(answers[kind]||answers.help)))}
el('suggestBuildForm').onsubmit=e=>{e.preventDefault();run(async()=>{if(attempt||!slug)return;const raw=el('suggestBudget').value.trim();if(!/^\d{1,9}(?:\.\d{1,2})?$/.test(raw))throw Error('Invalid budget');const [w,d='']=raw.split('.');buildAnswer=await getSuggestion(Number(w)*100+Number(d.padEnd(2,'0')),el('suggestGpu').checked);paintSuggestion(el('suggestBuildResult'),buildAnswer)})};
el('localAssistantForm').onsubmit=e=>{e.preventDefault();run(async()=>{if(attempt||!slug)return;const question=el('localAssistantQuestion').value;el('localAssistantQuestion').value='';assistantAnswer=null;el('localAssistantResult').replaceChildren();const intent=assistantIntent(question,currency);assistantAnswer=intent.kind==='build'?{kind:'build',suggestion:await getSuggestion(intent.budget,intent.gpu)}:{kind:intent.kind};paintAssistant()})};
document.addEventListener('techstore-languagechange',()=>{if(membershipInfo)paintMembership();paintSuggestion(el('suggestBuildResult'),buildAnswer);paintAssistant();renderBuild();renderCatalog()});

// Only enable if the browser model is already available; no automatic model download.
async function refreshModelAvailability(){const language=currentLanguage(),ready=await localModelReady(globalThis.LanguageModel,language);if(language===currentLanguage()){el('explainLocalBuild').hidden=el('generatedBuildNotice').hidden=!ready;controls()}}
refreshModelAvailability();document.addEventListener('techstore-languagechange',refreshModelAvailability);
el('explainLocalBuild').onclick=()=>run(async()=>{if(attempt||!slug||!build.size)return;const shop=slug,signature=JSON.stringify([...build.keys()]),language=currentLanguage(),out=el('generatedBuildResult');out.textContent='';try{const result=await explainBuildLocally(buildCompatibility([...build.values()]),{language});if(shop===slug&&language===currentLanguage()&&signature===JSON.stringify([...build.keys()]))out.textContent=result||tr('النموذج المحلي غير متاح؛ راجع نتائج التوافق.')}catch{if(shop===slug&&language===currentLanguage())out.textContent=tr('النموذج المحلي غير متاح؛ راجع نتائج التوافق.')}});
